window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-0b973a368c7a266f"]={"versions": [{"id": "FIG-0b973a368c7a266f", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Slave-to-Slave-Kommunikation im AUTOSAR-LIN-Kommunikationsstack. Dargestellt ist das Zusammenspiel zwischen dem Scheduling-Kontext des Betriebssystems bzw. BSW-Schedulers, dem LIN-Interface (<code>LinIf</code>) und dem LIN-Treiber (<code>Lin</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten und Lebenslinien:</p>\n<ul class=\"fig-list\">\n<li><code>BSW Task (OS task or cyclic call)</code>: Zyklischer Task- bzw. Ausführungskontext des Betriebssystems / BSW-Schedulers (gekennzeichnet durch das zyklische Task-Symbol).</li>\n<li><code>LinIf</code> («module»): LIN-Interface-Modul der Kommunikationsabstraktionsschicht.</li>\n<li><code>Lin</code> («module»): LIN-Treiber-Modul der Mikrocontroller-Abstraktionsschicht (MCAL).</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\">\n<li><code>LinIf_MainFunction()</code>: Zyklisch aufgerufene Hauptfunktion des LIN-Interface.</li>\n<li><code>RequestFrame()</code>: Modulinterne Prozedur des <code>LinIf</code> zur Frame-Anforderung bzw. Ablaufsteuerung.</li>\n<li><code>Lin_SendFrame(Channel, PduInfoPtr) :Std_ReturnType</code>: Treiber-API des <code>Lin</code>-Moduls zur Übertragung des LIN-Frames auf dem spezifizierten Kanal mit Rückgabewert vom Typ <code>Std_ReturnType</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Ausführungskontext <code>BSW Task (OS task or cyclic call)</code> stößt das Modul <code>LinIf</code> synchron über <code>LinIf_MainFunction()</code> an.</li>\n<li>Innerhalb des Aktivierungsbalkens führt <code>LinIf</code> einen internen Aufruf <code>RequestFrame()</code> auf sich selbst aus.</li>\n<li>Im weiteren Verlauf des Ablaufs ruft <code>LinIf</code> synchron die Treiberfunktion <code>Lin_SendFrame(Channel, PduInfoPtr) :Std_ReturnType</code> auf dem Modul <code>Lin</code> auf.</li>\n<li>Nach Abarbeitung der Frame-Sendeanforderung kehrt der Aufruf von <code>Lin</code> zu <code>LinIf</code> zurück (gestrichelte Rückkehrnachricht).</li>\n<li>Abschließend kehrt <code>LinIf_MainFunction()</code> zum aufrufenden BSW-Task-Kontext zurück (gestrichelte Rückkehrnachricht).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Sequenz verdeutlicht, dass bei einer Slave-to-Slave-Kommunikation der Master (repräsentiert durch den LIN-Stack) den Übertragungsrahmen anstoßen muss, indem das LIN-Interface innerhalb seines zyklischen Task-Kontexts (<code>LinIf_MainFunction</code>) den Header/Frame über die Treiber-API <code>Lin_SendFrame</code> initiiert. Für Implementierer ist sicherzustellen, dass die Task-Zykluszeit der Schedule-Tabelle entspricht und der LIN-Treiber den Aufruf synchron verarbeitet sowie seinen Status via <code>Std_ReturnType</code> an das LIN-Interface zurückmeldet.</p>"}, {"id": "FIG-ecb44f2f1d8a91db", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Slave-to-Slave-Kommunikation im AUTOSAR-LIN-Kommunikationsstack. Dargestellt ist das Zusammenspiel zwischen dem Scheduling-Kontext des Betriebssystems bzw. BSW-Schedulers, dem LIN-Interface (<code>LinIf</code>) und dem LIN-Treiber (<code>Lin</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten und Lebenslinien:</p>\n<ul class=\"fig-list\">\n<li><code>BSW Task (OS task or cyclic call)</code>: Zyklischer Task- bzw. Ausführungskontext des Betriebssystems / BSW-Schedulers (gekennzeichnet durch das zyklische Task-Symbol).</li>\n<li><code>LinIf</code> («module»): LIN-Interface-Modul der Kommunikationsabstraktionsschicht.</li>\n<li><code>Lin</code> («module»): LIN-Treiber-Modul der Mikrocontroller-Abstraktionsschicht (MCAL).</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\">\n<li><code>LinIf_MainFunction()</code>: Zyklisch aufgerufene Hauptfunktion des LIN-Interface.</li>\n<li><code>RequestFrame()</code>: Modulinterne Prozedur des <code>LinIf</code> zur Frame-Anforderung bzw. Ablaufsteuerung.</li>\n<li><code>Lin_SendFrame(Channel, PduInfoPtr)</code>: Treiber-API des <code>Lin</code>-Moduls zur Übertragung des LIN-Frames auf dem spezifizierten Kanal.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Ausführungskontext <code>BSW Task (OS task or cyclic call)</code> stößt das Modul <code>LinIf</code> synchron über <code>LinIf_MainFunction()</code> an.</li>\n<li>Innerhalb des Aktivierungsbalkens führt <code>LinIf</code> einen internen Aufruf <code>RequestFrame()</code> auf sich selbst aus.</li>\n<li>Im weiteren Verlauf des Ablaufs ruft <code>LinIf</code> synchron die Treiberfunktion <code>Lin_SendFrame(Channel, PduInfoPtr)</code> auf dem Modul <code>Lin</code> auf.</li>\n<li>Nach Abarbeitung der Frame-Sendeanforderung kehrt der Aufruf von <code>Lin</code> zu <code>LinIf</code> zurück (gestrichelte Rückkehrnachricht).</li>\n<li>Abschließend kehrt <code>LinIf_MainFunction()</code> zum aufrufenden BSW-Task-Kontext zurück (gestrichelte Rückkehrnachricht).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Sequenz verdeutlicht, dass bei einer Slave-to-Slave-Kommunikation der Master (repräsentiert durch den LIN-Stack) den Übertragungsrahmen anstoßen muss, indem das LIN-Interface innerhalb seines zyklischen Task-Kontexts (<code>LinIf_MainFunction</code>) den Header/Frame über die Treiber-API <code>Lin_SendFrame</code> initiiert. Für Implementierer ist sicherzustellen, dass die Task-Zykluszeit der Schedule-Tabelle entspricht und der Aufruf von <code>Lin_SendFrame</code> im MCAL-Treiber korrekt abgesetzt wird.</p>"}, {"id": "FIG-8a98bac3189e57e1", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Slave-to-Slave-Kommunikation im AUTOSAR-LIN-Kommunikationsstack. Dargestellt ist das Zusammenspiel zwischen dem Scheduling-Kontext des Betriebssystems bzw. BSW-Schedulers, dem LIN-Interface (<code>LinIf</code>) und dem LIN-Treiber (<code>Lin</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten und Lebenslinien:</p>\n<ul class=\"fig-list\">\n<li><code>BSW Task (OS task or cyclic call)</code>: Zyklischer Task- bzw. Ausführungskontext des Betriebssystems / BSW-Schedulers (gekennzeichnet durch das zyklische Task-Symbol).</li>\n<li><code>LinIf</code> («module»): LIN-Interface-Modul der Kommunikationsabstraktionsschicht.</li>\n<li><code>Lin</code> («module»): LIN-Treiber-Modul der Mikrocontroller-Abstraktionsschicht (MCAL).</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\">\n<li><code>LinIf_MainFunction()</code>: Zyklisch aufgerufene Hauptfunktion des LIN-Interface.</li>\n<li><code>RequestFrame()</code>: Modulinterne Prozedur des <code>LinIf</code> zur Frame-Anforderung bzw. Ablaufsteuerung.</li>\n<li><code>Lin_SendFrame(Channel, PduInfoPtr)</code>: Treiber-API des <code>Lin</code>-Moduls zur Übertragung des LIN-Frames auf dem spezifizierten Kanal.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Ausführungskontext <code>BSW Task (OS task or cyclic call)</code> stößt das Modul <code>LinIf</code> synchron über <code>LinIf_MainFunction()</code> an.</li>\n<li>Innerhalb des Aktivierungsbalkens führt <code>LinIf</code> einen internen Aufruf <code>RequestFrame()</code> auf sich selbst aus.</li>\n<li>Im weiteren Verlauf des Ablaufs ruft <code>LinIf</code> synchron die Treiberfunktion <code>Lin_SendFrame(Channel, PduInfoPtr)</code> auf dem Modul <code>Lin</code> auf.</li>\n<li>Nach Abarbeitung der Frame-Sendeanforderung kehrt der Aufruf von <code>Lin</code> zu <code>LinIf</code> zurück (gestrichelte Rückkehrnachricht).</li>\n<li>Abschließend kehrt <code>LinIf_MainFunction()</code> zum aufrufenden BSW-Task-Kontext zurück (gestrichelte Rückkehrnachricht).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Sequenz verdeutlicht, dass bei einer Slave-to-Slave-Kommunikation der Master (repräsentiert durch den LIN-Stack) den Übertragungsrahmen anstoßen muss, indem das LIN-Interface innerhalb seines zyklischen Task-Kontexts (<code>LinIf_MainFunction</code>) den Header/Frame über die Treiber-API <code>Lin_SendFrame</code> initiiert. Für Implementierer ist sicherzustellen, dass die Task-Zykluszeit der Schedule-Tabelle entspricht und der Aufruf von <code>Lin_SendFrame</code> im MCAL-Treiber korrekt abgesetzt wird.</p>"}, {"id": "FIG-3a81192bedba104d", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Slave-to-Slave-Kommunikation im AUTOSAR-LIN-Kommunikationsstack. Dargestellt ist das Zusammenspiel zwischen dem Scheduling-Kontext des Betriebssystems bzw. BSW-Schedulers, dem LIN-Interface (<code>LinIf</code>) und dem LIN-Treiber (<code>Lin</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten und Lebenslinien:</p>\n<ul class=\"fig-list\">\n<li><code>BSW Task (OS task or cyclic call)</code>: Zyklischer Task- bzw. Ausführungskontext des Betriebssystems / BSW-Schedulers (gekennzeichnet durch das zyklische Task-Symbol).</li>\n<li><code>LinIf</code> («module»): LIN-Interface-Modul der Kommunikationsabstraktionsschicht.</li>\n<li><code>Lin</code> («module»): LIN-Treiber-Modul der Mikrocontroller-Abstraktionsschicht (MCAL).</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\">\n<li><code>LinIf_MainFunction_&lt;ChannelId&gt;()</code>: Kanalspezifische, zyklisch aufgerufene Hauptfunktion des LIN-Interface.</li>\n<li><code>RequestFrame()</code>: Modulinterne Prozedur des <code>LinIf</code> zur Frame-Anforderung bzw. Ablaufsteuerung.</li>\n<li><code>Lin_SendFrame(Channel, PduInfoPtr)</code>: Treiber-API des <code>Lin</code>-Moduls zur Übertragung des LIN-Frames auf dem spezifizierten Kanal.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Ausführungskontext <code>BSW Task (OS task or cyclic call)</code> stößt das Modul <code>LinIf</code> synchron über die kanalspezifische Funktion <code>LinIf_MainFunction_&lt;ChannelId&gt;()</code> an.</li>\n<li>Innerhalb des Aktivierungsbalkens führt <code>LinIf</code> einen internen Aufruf <code>RequestFrame()</code> auf sich selbst aus.</li>\n<li>Im weiteren Verlauf des Ablaufs ruft <code>LinIf</code> synchron die Treiberfunktion <code>Lin_SendFrame(Channel, PduInfoPtr)</code> auf dem Modul <code>Lin</code> auf.</li>\n<li>Nach Abarbeitung der Frame-Sendeanforderung kehrt der Aufruf von <code>Lin</code> zu <code>LinIf</code> zurück (gestrichelte Rückkehrnachricht).</li>\n<li>Abschließend kehrt <code>LinIf_MainFunction_&lt;ChannelId&gt;()</code> zum aufrufenden BSW-Task-Kontext zurück (gestrichelte Rückkehrnachricht).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Sequenz verdeutlicht, dass bei einer Slave-to-Slave-Kommunikation der Master (repräsentiert durch den LIN-Stack) den Übertragungsrahmen anstoßen muss, indem das LIN-Interface innerhalb seines zyklischen, kanalspezifischen Task-Kontexts (<code>LinIf_MainFunction_&lt;ChannelId&gt;</code>) den Header/Frame über die Treiber-API <code>Lin_SendFrame</code> initiiert. Für Implementierer ist sicherzustellen, dass die Konfiguration und Taktung der kanalspezifischen Hauptfunktionen an die jeweiligen LIN-Kanäle angepasst sind.</p>"}], "trans": [{"from": "FIG-0b973a368c7a266f", "to": "FIG-ecb44f2f1d8a91db", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Operationsaufruf <code>Lin_SendFrame(Channel, PduInfoPtr)</code>: Die explizite Angabe des Rückgabetyps <code>:Std_ReturnType</code> an der Aufrufbeschriftung entfällt.</li>\n</ul>"}, {"from": "FIG-ecb44f2f1d8a91db", "to": "FIG-8a98bac3189e57e1", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-8a98bac3189e57e1", "to": "FIG-3a81192bedba104d", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Aufruf der zyklischen Hauptfunktion: Der Aufruf <code>LinIf_MainFunction()</code> wird durch die kanalspezifische Variante <code>LinIf_MainFunction_&lt;ChannelId&gt;()</code> ersetzt.</li>\n</ul>"}]};
